mat2 calculerMatriceRotation(float angleRotation)
{
    float cosinusAngle = cos(angleRotation);
    float sinusAngle = sin(angleRotation);
    return mat2(cosinusAngle, -sinusAngle, sinusAngle, cosinusAngle);
}

vec3 renduRaymarching(vec2 coordonneesUV)
{
    float tempsCourant = iTime;
    float distanceAccumulee = 0.0;
    vec3 couleurAccumulee = vec3(0.0);

    // Global camera rotations over time
    // - Multiply factors (e.g. 0.05, -0.78) to speed up or slow down camera movement
    mat2 matriceRotationY = calculerMatriceRotation(tempsCourant * 0.05);
    mat2 matriceRotationX = calculerMatriceRotation(tempsCourant * -0.78);

    // Internal fractal morphing rotation
    // - 3.2 is the base orientation offset
    // - 0.05 controls how strongly the fractal twists over time
    mat2 matriceRotationFractale = calculerMatriceRotation(3.2 + sin(tempsCourant * 0.1) * 0.05);

    // Camera forward travel speed along Z axis
    // - Increase 0.8 to travel faster through the fractal space
    vec3 avancementZ = vec3(0.0, 0.0, tempsCourant * 0.8);

    // Raymarching step count
    // - Increase for higher fractal precision (more heavy on GPU)
    // - Decrease for better performance
    for(int indicePas = 0; indicePas < 75; indicePas++)
    {
        float valeurIndice = float(indicePas);
        vec3 positionRayon = vec3(coordonneesUV * distanceAccumulee, distanceAccumulee);
        positionRayon.xz *= matriceRotationY;
        positionRayon.yz *= matriceRotationX;
        positionRayon += avancementZ;

        // Ray origin perturbation per step
        positionRayon += 0.8 - valeurIndice * 5e-5;

        // Initial fractal scale and mass accumulator
        // - Modify 3.5 to change base fractal size
        float facteurEchelle = 3.5;
        float facteurMasse = 1.0;

        // Fractal iteration count
        // - Higher values reveal finer recursive details
        for(int indiceIteration = 0; indiceIteration < 6; indiceIteration++)
        {
            // Spatial folding / repetition domain size
            positionRayon = mod(positionRayon - 1.0, 2.0) - 1.0;
            positionRayon.xz *= matriceRotationFractale;

            // Sphere inversion factor
            // - Adjust 0.73 to change geometry density and structure
            facteurMasse = max(dot(positionRayon, positionRayon) * 0.73, 0.0);
            facteurEchelle /= facteurMasse;
            positionRayon = abs(positionRayon) / facteurMasse;

            // Vertical offset in fractal fold
            // - Change 0.63 to drastically alter the fractal shape
            positionRayon.y += 0.63;
        }

        // Distance estimate step multiplier
        // - Lower than 0.45 avoids artifacts; higher values render faster
        facteurMasse = abs(positionRayon.x) / max(facteurEchelle, 0.001);
        float pasProgression = max(facteurMasse * 0.45, 0.0012);
        distanceAccumulee += pasProgression;

        // Color palette controls
        float logEchelle = log(max(facteurEchelle, 0.001));

        // Primary color spectrum cycle
        // - Adjust vec3(0.0, 0.6, 1.2) to shift RGB color phases
        vec3 teintePrincipale = 0.5 + 0.5 * cos(vec3(0.0, 0.6, 1.2) + logEchelle * 0.8 + tempsCourant * 0.2);

        // Secondary warm highlight tone
        // - Adjust vec3(1.4, 0.8, 0.4) to change tint hue/brightness
        vec3 teinteSecondaire = vec3(1.4, 0.8, 0.4) * (1.3 - sin(vec3(0.0, 1.0, 6.1) + logEchelle));

        // Blending ratio between primary and secondary tints (0.0 = primary, 1.0 = secondary)
        vec3 teinteFractale = mix(teintePrincipale, teinteSecondaire, 0.6);

        // Volumetric glow intensity
        // - 2500.0 controls glow sharpness around fractal surface
        float intensiteLumiere = exp(-facteurMasse * 2500.0);

        // Distance fog / depth shadow factor
        // - 0.15 controls how fast distant geometry fades out
        float ombrePortee = exp(-distanceAccumulee * 0.15);

        // Accumulator step gain
        // - 0.012 controls total brightness accumulation speed per iteration
        couleurAccumulee += 0.012 * intensiteLumiere * teinteFractale * ombrePortee;

        // Max render distance cutoff and ray brightness cap
        if(distanceAccumulee > 18.0 || couleurAccumulee.r > 2.0) break;
    }

    return couleurAccumulee;
}

void mainImage(out vec4 couleurSortie, in vec2 coordonneesFragment)
{
    vec2 coordonneesUV = (coordonneesFragment - 0.5 * iResolution.xy) / iResolution.y;
    vec2 coordonneesNormalisees = coordonneesFragment / iResolution.xy;

    vec3 couleurLumiere = renduRaymarching(coordonneesUV);

    // Chromatic aberration intensity
    // - Adjust 0.003 to increase or decrease edge color splitting
    float decalageAberration = 0.003 * length(coordonneesUV);
    couleurLumiere.r *= (1.0 + decalageAberration);
    couleurLumiere.b *= (1.0 - decalageAberration);

    // Fake bloom / soft glow intensity
    // - Adjust pow exponent (1.5) and factor (0.35) for softer or stronger highlights
    vec3 couleurFloue = pow(couleurLumiere, vec3(1.5)) * 0.35;
    couleurLumiere += couleurFloue;

    // Tonemapping compression & Gamma correction
    // - Adjust vec3(0.2) to change tone mapping white point threshold
    // - 0.4545 is gamma 2.2 correction (1.0 / 2.2)
    couleurLumiere = couleurLumiere / (vec3(0.2) + couleurLumiere);
    couleurLumiere = pow(couleurLumiere, vec3(0.4545));

    // Vignette post-processing effect
    // - Adjust 30.0 and 0.25 to tweak edge darkness softness and spread
    float vignette = coordonneesNormalisees.x * coordonneesNormalisees.y * (1.0 - coordonneesNormalisees.x) * (1.0 - coordonneesNormalisees.y);
    vignette = clamp(pow(30.0 * vignette, 0.25), 0.0, 1.0);
    couleurLumiere *= vignette;

    couleurSortie = vec4(couleurLumiere, 1.0);
}
